using System;
using UnityEditor;
using UnityEngine;

namespace AccessoryPrefabMaker
{
    // The Accessory Extractor logo: a banner at the top of the windows (dark or light to match the editor skin) and the
    // tab icon. The images are inline (ApmLogoData.cs, generated by Tools~/logo/logo_gen.py) so no image files are needed.
    static partial class ApmLogo
    {
        static Texture2D bannerDark, bannerLight, icon;
        static Texture2D Load(ref Texture2D texture, string png)
        {
            if (texture) return texture;
            texture = new Texture2D(2, 2, TextureFormat.RGBA32, false, false) { hideFlags = HideFlags.HideAndDontSave, filterMode = FilterMode.Bilinear, wrapMode = TextureWrapMode.Clamp };
            texture.LoadImage(Convert.FromBase64String(png));
            return texture;
        }
        public static Texture2D Icon { get { return Load(ref icon, IconPng); } }
        // Draws the banner at its design width (480), smaller when the window is narrow.
        public static void Banner(float available)
        {
            var texture = EditorGUIUtility.isProSkin ? Load(ref bannerDark, BannerDarkPng) : Load(ref bannerLight, BannerLightPng);
            float width = Mathf.Clamp(available, 120, 480), height = width * texture.height / texture.width;
            var rect = GUILayoutUtility.GetRect(width, height, GUILayout.Width(width), GUILayout.Height(height));
            if (Event.current.type == EventType.Repaint) GUI.DrawTexture(rect, texture, ScaleMode.ScaleToFit, true);
        }
    }
}
